from concurrent.futures import ThreadPoolExecutor

def execute_dag(nodes, max_workers, compute):
    if not isinstance(nodes, dict) or any(dep not in nodes for deps in nodes.values() for dep in deps):
        raise ValueError('invalid dependency graph')
    if isinstance(max_workers, bool) or not isinstance(max_workers, int) or not 1 <= max_workers <= 64:
        raise ValueError('invalid worker count')
    if not callable(compute):
        raise ValueError('compute callback required')
    with ThreadPoolExecutor(max_workers=max_workers) as pool:
        def resolve(name):
            dependencies = [pool.submit(resolve, dep) for dep in nodes[name]]
            return compute(name, [future.result() for future in dependencies])
        futures = {name: pool.submit(resolve, name) for name in nodes}
        return {name: future.result() for name, future in futures.items()}

