def execute_dag(nodes,max_workers,compute):
    with ThreadPoolExecutor(max_workers=max_workers) as pool:
        def run(name):
            children=[pool.submit(run,dep) for dep in nodes[name]]
            return compute(name,[future.result() for future in children])
        roots=[name for name in nodes if not any(name in deps for deps in nodes.values())]
        return {name:pool.submit(run,name).result() for name in roots}

